func thDiagonal(rot int32) int32 {
	// 1 when an angle (centi-degrees) is at least 3 degrees off every right angle: text set on the diagonal.
	var r int32 = rot % 9000
	var dev int32 = 0
	if r < 0 {
		r += 9000
	}
	dev = r
	if (9000 - r) < dev {
		dev = 9000 - r
	}
	if dev >= 300 {
		return 1
	}
	return 0
}

func thSetAside(gl *port.Cells, mk *port.Cells, wd *port.Cells, w int32) int32 {
	// The ledger reason of a word set aside as `invisible` (white, zero-size, transparent, off by an optional-content group,
	// occluded): `watermark` when it is also what a watermark is, an /Artifact of subtype Watermark or text on the diagonal
	// (the page hides its watermark; it is still a watermark, as the furniture stage's geometry would have said, D241).
	var g0 int32 = evidence.WdGet(wd, w, evidence.WfGfirst())
	var art int32 = evidence.MkArtifactOf(mk, evidence.GlGet(gl, g0, evidence.GfMark()))
	if (art > 0) && ((art % 16) == evidence.AsWatermark()) {
		return model.DrWatermark()
	}
	if thDiagonal(evidence.WdGet(wd, w, evidence.HdRot())) == 1 {
		return model.DrWatermark()
	}
	return model.DrInvisible()
}

func thClass(gl *port.Cells, mk *port.Cells, im *port.Cells, epages *port.Cells, wd *port.Cells, w int32, ip int32) int32 {
	// What becomes of word w: 0 it stays; -1 it stays as a `hidden-text` word (occluded by an image covering `th-page-image` of
	// the page); else the ledger reason (`dr`) it is set aside under. `ip` is the first image row of the word's page.
	var g0 int32 = evidence.WdGet(wd, w, evidence.WfGfirst())
	var pgno int32 = evidence.WdGet(wd, w, evidence.HdPage())
	var vis int32 = 0
	var by int32 = 0
	var k int32 = ip
	var ep int32 = 0
	var area int64 = int64(0)
	if evidence.WdGet(wd, w, evidence.WfGcount()) <= 0 {
		return 0
	}
	vis = evidence.GlGet(gl, g0, evidence.GfVis())
	if vis == 0 {
		return 0
	}
	if vis == evidence.VzClipped() {
		return model.DrClipped()
	}
	if vis == evidence.VzOffpage() {
		return model.DrOffpage()
	}
	if vis == evidence.VzOccluded() {
		by = evidence.GlGet(gl, g0, evidence.GfVby())
		ep = evidence.EvPageRow(epages, pgno)
		if ep >= 0 {
			area = int64(evidence.EpGet(epages, ep, evidence.EpfWidth())) * int64(evidence.EpGet(epages, ep, evidence.EpfHeight()))
			for (k < evidence.ImCount(im)) && (evidence.ImGet(im, k, evidence.MfPage()) == pgno) {
				if evidence.ImGet(im, k, evidence.MfZ()) == by {
					if ((int64(evidence.ImGet(im, k, evidence.MfX1())-evidence.ImGet(im, k, evidence.MfX0())) * int64(evidence.ImGet(im, k, evidence.MfY1())-evidence.ImGet(im, k, evidence.MfY0()))) * int64(1000)) >= (area * int64(ThPageImage())) {
						if area > int64(0) {
							return -1
						}
					}
				}
				k += 1
			}
		}
	}
	return thSetAside(gl, mk, wd, w)
}

func thDominant(ln *port.Cells, l0 int32, l1 int32, sc *port.Cells) int32 {
	// The page's dominant text angle (`rot` of its lines l0..l1): the 1-degree bucket most lines fall in (the lowest on a tie),
	// answered as the `rot` of the first line in it. `sc` is 360 cells of scratch.
	var i int32 = 0
	var b int32 = 0
	var best int32 = 0
	var bc int32 = 0
	port.CellsDrop(sc, 0)
	for i < 360 {
		port.CellsPush(sc, 0)
		i += 1
	}
	i = l0
	for i < l1 {
		b = evidence.LnGet(ln, i, evidence.LhRot()) / 100
		if (b >= 0) && (b < 360) {
			port.CellsSet(sc, b, port.CellsAt(sc, b)+1)
		}
		i += 1
	}
	i = 0
	for i < 360 {
		if port.CellsAt(sc, i) > bc {
			bc = port.CellsAt(sc, i)
			best = i
		}
		i += 1
	}
	i = l0
	for i < l1 {
		if (evidence.LnGet(ln, i, evidence.LhRot()) / 100) == best {
			return evidence.LnGet(ln, i, evidence.LhRot())
		}
		i += 1
	}
	return 0
}

func thRemeasure(fl *port.Cells, fw *port.Cells, l int32, first int32, cnt int32) int32 {
	// Re-measure line l of `fl` from its remaining words (a run of `fw`): the union of their boxes, the baseline from the first
	// word's start to the last word's end.
	var x0 int32 = port.CellsAt(fw, (first*24)+1)
	var y0 int32 = port.CellsAt(fw, (first*24)+2)
	var x1 int32 = port.CellsAt(fw, (first*24)+3)
	var y1 int32 = port.CellsAt(fw, (first*24)+4)
	var i int32 = 1
	var v int32 = 0
	for i < cnt {
		v = port.CellsAt(fw, ((first+i)*24)+1)
		if v < x0 {
			x0 = v
		}
		v = port.CellsAt(fw, ((first+i)*24)+2)
		if v < y0 {
			y0 = v
		}
		v = port.CellsAt(fw, ((first+i)*24)+3)
		if v > x1 {
			x1 = v
		}
		v = port.CellsAt(fw, ((first+i)*24)+4)
		if v > y1 {
			y1 = v
		}
		i += 1
	}
	port.CellsSet(fl, (l*16)+1, x0)
	port.CellsSet(fl, (l*16)+2, y0)
	port.CellsSet(fl, (l*16)+3, x1)
	port.CellsSet(fl, (l*16)+4, y1)
	port.CellsSet(fl, (l*16)+5, port.CellsAt(fw, (first*24)+5))
	port.CellsSet(fl, (l*16)+6, port.CellsAt(fw, (first*24)+6))
	port.CellsSet(fl, (l*16)+7, port.CellsAt(fw, ((first+(cnt-1))*24)+7))
	port.CellsSet(fl, (l*16)+8, port.CellsAt(fw, ((first+(cnt-1))*24)+8))
	return 0
}

func thRamp(v int32, ok int32, bad int32) int32 {
	// 1000 up to `ok`, 0 from `bad`, linear between.
	if v <= ok {
		return 1000
	}
	if v >= bad {
		return 0
	}
	return ((bad - v) * 1000) / (bad - ok)
}

func thFloor(c int32) int32 {
	if c < 50 {
		return 50
	}
	return c
}

func ThScore(mapped int32, garbage int32, overlap int32, gap int32) int32 {
	// The score of the pooled per-mille components: the weighted harmonic mean (weights 4, 3, 2, 1) of mapped, 1000 - garbage, the
	// overlap ramp (`th-overlap-ok` to 1000) and the gap ramp (`th-gap-ok` to `th-gap-bad`), each floored at 50, scaled by
	// `(1000 + weakest) / 2000`, the weakest being the smallest component before the floor (D150's shape).
	var c0 int32 = mapped
	var c1 int32 = 1000 - garbage
	var c2 int32 = thRamp(overlap, ThOverlapOk(), 1000)
	var c3 int32 = thRamp(gap, ThGapOk(), ThGapBad())
	var weakest int32 = c0
	var sum int64 = int64(0)
	var h int32 = 0
	if c1 < weakest {
		weakest = c1
	}
	if c2 < weakest {
		weakest = c2
	}
	if c3 < weakest {
		weakest = c3
	}
	sum = (int64(4000000/thFloor(c0)) + int64(3000000/thFloor(c1))) + (int64(2000000/thFloor(c2)) + int64(1000000/thFloor(c3)))
	h = int32(int64(10000000) / sum)
	if weakest < 0 {
		weakest = 0
	}
	return (h * (1000 + weakest)) / 2000
}

func thHlRow(hl *port.Cells, from int32, page int32, font int32) int32 {
	// The row of `hl` at or after `from` for (page, font), -1 when none.
	var n int32 = player.HlCount(hl)
	var i int32 = from
	for i < n {
		if (player.HlGet(hl, i, player.HlfPage()) == page) && (player.HlGet(hl, i, player.HlfSubject()) == font) {
			return i
		}
		i += 1
	}
	return -1
}

func thHlAdd(hl *port.Cells, r int32, f int32, v int32) int32 {
	var old int32 = player.HlGet(hl, r, f)
	player.HlSet(hl, r, f, old+v)
	return 0
}

func thHlDiv(hl *port.Cells, r int32, f int32, n int32) int32 {
	var old int32 = player.HlGet(hl, r, f)
	player.HlSet(hl, r, f, old/n)
	return 0
}

func ThHealth(feats *port.Cells, fw *port.Cells, hl *port.Cells) int32 {
	// Per (font, page) of the flow `fw`: the pooled stage-1 columns 2-5, glyph-weighted (4 and 5 are each word's worst, averaged),
	// as `hl` rows (kind font-page, subject the font row; components mapped, garbage, overlap, gap; agreement and ink -1 until
	// P7.2) and their score, which is written into each word's `xt` column 13. Answers the rows made.
	var nw int32 = player.FwCount(fw)
	var h0 int32 = player.HlCount(hl)
	var i int32 = 0
	var hstart int32 = player.HlCount(hl)
	var curpage int32 = -1
	var r int32 = 0
	var ft int32 = 0
	var n int32 = 0
	var pgno int32 = 0
	var sc0 int32 = 0
	var font int32 = 0
	for i < nw {
		n = port.CellsAt(fw, (i*24)+18)
		ft = port.CellsAt(fw, (i*24)+15)
		if (n > 0) && (ft >= 0) {
			pgno = port.CellsAt(fw, i*24)
			font = port.CellsAt(fw, (i*24)+19)
			if pgno != curpage {
				curpage = pgno
				hstart = player.HlCount(hl)
			}
			r = thHlRow(hl, hstart, pgno, font)
			if r < 0 {
				r = player.HlNew(hl, player.PlhFontPage(), pgno, font)
				player.HlSet(hl, r, player.HlfMapped(), 0)
				player.HlSet(hl, r, player.HlfGarbage(), 0)
				player.HlSet(hl, r, player.HlfOverlap(), 0)
				player.HlSet(hl, r, player.HlfGap(), 0)
				player.HlSet(hl, r, 11, 0)
			}
			thHlAdd(hl, r, player.HlfMapped(), evidence.FeGet(feats, ft, evidence.XtTrust())*n)
			thHlAdd(hl, r, player.HlfGarbage(), evidence.FeGet(feats, ft, evidence.XtBadCp())*n)
			thHlAdd(hl, r, player.HlfOverlap(), evidence.FeGet(feats, ft, evidence.XtOverlap())*n)
			thHlAdd(hl, r, player.HlfGap(), evidence.FeGet(feats, ft, evidence.XtGapAnomaly())*n)
			thHlAdd(hl, r, 11, n)
		}
		i += 1
	}
	i = h0
	for i < player.HlCount(hl) {
		n = player.HlGet(hl, i, 11)
		thHlDiv(hl, i, player.HlfMapped(), n)
		thHlDiv(hl, i, player.HlfGarbage(), n)
		thHlDiv(hl, i, player.HlfOverlap(), n)
		thHlDiv(hl, i, player.HlfGap(), n)
		sc0 = ThScore(player.HlGet(hl, i, player.HlfMapped()), player.HlGet(hl, i, player.HlfGarbage()), player.HlGet(hl, i, player.HlfOverlap()), player.HlGet(hl, i, player.HlfGap()))
		player.HlSet(hl, i, player.HlfScore(), sc0)
		player.HlSet(hl, i, 11, 0)
		i += 1
	}
	// each word's column 13: its (font, page)'s score
	i = 0
	curpage = -1
	hstart = h0
	for i < nw {
		n = port.CellsAt(fw, (i*24)+18)
		ft = port.CellsAt(fw, (i*24)+15)
		if (n > 0) && (ft >= 0) {
			pgno = port.CellsAt(fw, i*24)
			font = port.CellsAt(fw, (i*24)+19)
			if pgno != curpage {
				curpage = pgno
				for (hstart < player.HlCount(hl)) && (player.HlGet(hl, hstart, player.HlfPage()) != pgno) {
					hstart += 1
				}
			}
			r = thHlRow(hl, hstart, pgno, font)
			if r >= 0 {
				evidence.FeSet(feats, ft, evidence.XtFontHealth(), player.HlGet(hl, r, player.HlfScore()))
			}
		}
		i += 1
	}
	return player.HlCount(hl) - h0
}

func ThRun(pg *port.Cells, gl *port.Cells, et *port.Cells, mk *port.Cells, fnt *port.Cells, wd *port.Cells, ln *port.Cells, im *port.Cells, epages *port.Cells, feats *port.Cells, fw *port.Cells, fl *port.Cells, fa *port.Cells, hl *port.Cells, sc *port.Cells) int32 {
	// P7.0's stage (D195): `epages` of every page, the stage-1 features of every word of `wd`, the triage of `wd`/`ln` into the
	// flow `fw`/`fl` and the set-aside `fa`, and the health of the fonts (`hl`, column 13). `sc` is 360 cells of scratch. Answers 0.
	var nl int32 = evidence.LnCount(ln)
	var l int32 = 0
	var l1 int32 = 0
	var pgno int32 = 0
	var dom int32 = 0
	var ip int32 = 0
	var w int32 = 0
	var wend int32 = 0
	var medh int32 = 0
	var cls int32 = 0
	var kept int32 = 0
	var first int32 = 0
	var flRow int32 = 0
	var fr int32 = 0
	var frow int32 = 0
	var dropped int32 = 0
	ThEpages(pg, wd, epages)
	for l < nl {
		pgno = evidence.LnGet(ln, l, evidence.LhPage())
		l1 = l
		for (l1 < nl) && (evidence.LnGet(ln, l1, evidence.LhPage()) == pgno) {
			l1 += 1
		}
		dom = thDominant(ln, l, l1, sc)
		for (ip < evidence.ImCount(im)) && (evidence.ImGet(im, ip, evidence.MfPage()) < pgno) {
			ip += 1
		}
		for l < l1 {
			w = evidence.LnGet(ln, l, evidence.LhFirst())
			wend = w + evidence.LnGet(ln, l, evidence.LhCount())
			medh = thLineMedian(wd, w, evidence.LnGet(ln, l, evidence.LhCount()))
			kept = 0
			dropped = 0
			first = player.FwCount(fw)
			flRow = player.FlCount(fl)
			for w < wend {
				frow = EvFeatText(feats, epages, et, gl, fnt, mk, wd, ln, w, l, dom, medh)
				cls = thClass(gl, mk, im, epages, wd, w, ip)
				if cls > 0 {
					player.FaNew(fa, pgno, evidence.WdGet(wd, w, evidence.HdX0()), evidence.WdGet(wd, w, evidence.HdY0()), evidence.WdGet(wd, w, evidence.HdX1()), evidence.WdGet(wd, w, evidence.HdY1()), cls, evidence.EaWords(), w)
					dropped = 1
				} else {
					fr = player.FwCopyWord(fw, wd, w, flRow)
					port.CellsSet(fw, (fr*24)+evidence.HdFeat(), frow)
					if cls < 0 {
						port.CellsSet(fw, (fr*24)+evidence.WfSrc(), model.SrHiddenText())
					}
					kept += 1
				}
				w += 1
			}
			if kept > 0 {
				player.FlCopyLine(fl, ln, l, first, kept)
				if dropped == 1 {
					thRemeasure(fl, fw, flRow, first, kept)
				}
			}
			l += 1
		}
	}
	ThHealth(feats, fw, hl)
	return 0
}

func ThAppend(wd *port.Cells, ln *port.Cells, fw *port.Cells, fl *port.Cells, l0 int32) int32 {
	// The lines `l0` onward of `ln` (and their words), copied as they are onto the flow `fw`/`fl`: the OCR lines of the scanned
	// pages (P6.5), which join `wd`/`ln` after the text layer's own and have no glyphs to triage. Answers the lines copied.
	var nl int32 = evidence.LnCount(ln)
	var l int32 = l0
	var w int32 = 0
	var wend int32 = 0
	var first int32 = 0
	var lc int32 = 0
	var lrow int32 = 0
	for l < nl {
		w = evidence.LnGet(ln, l, evidence.LhFirst())
		lc = evidence.LnGet(ln, l, evidence.LhCount())
		wend = w + lc
		first = player.FwCount(fw)
		lrow = player.FlCount(fl)
		for w < wend {
			player.FwCopyWord(fw, wd, w, lrow)
			w += 1
		}
		player.FlCopyLine(fl, ln, l, first, lc)
		l += 1
	}
	return nl - l0
}

func ThWrite(fa *port.Cells, wd *port.Cells, et *port.Cells, ledger *port.Cells, text *port.Cells, tmp *port.Cells, tt *port.Cells) int32 {
	// The set-aside words as ledger rows: a run of `fa` rows of one reason, page and line is ONE row, its box the union of theirs,
	// its text the words joined by a space (NFC, ligatures folded, as every ledger text), conf 1000 (a check says invisible only when
	// certain), src `text`. `tt` and `tmp` are scratch. Answers the rows written.
	var n int32 = player.FaCount(fa)
	var i int32 = 0
	var j int32 = 0
	var k int32 = 0
	var s int32 = 0
	var e int32 = 0
	var x0 int32 = 0
	var y0 int32 = 0
	var x1 int32 = 0
	var y1 int32 = 0
	var lr int32 = 0
	var t0 int32 = 0
	var rows int32 = 0
	var line int32 = 0
	var w int32 = 0
	for i < n {
		j = i + 1
		w = player.FaGet(fa, i, 7)
		line = evidence.WdGet(wd, w, evidence.HdLine())
		for (j < n) && ((player.FaGet(fa, j, 5) == player.FaGet(fa, i, 5)) && ((player.FaGet(fa, j, 0) == player.FaGet(fa, i, 0)) && (evidence.WdGet(wd, player.FaGet(fa, j, 7), evidence.HdLine()) == line))) {
			j += 1
		}
		x0 = player.FaGet(fa, i, 1)
		y0 = player.FaGet(fa, i, 2)
		x1 = player.FaGet(fa, i, 3)
		y1 = player.FaGet(fa, i, 4)
		port.CellsDrop(tt, 0)
		k = i
		for k < j {
			if k > i {
				port.CellsPush(tt, 32)
			}
			if player.FaGet(fa, k, 1) < x0 {
				x0 = player.FaGet(fa, k, 1)
			}
			if player.FaGet(fa, k, 2) < y0 {
				y0 = player.FaGet(fa, k, 2)
			}
			if player.FaGet(fa, k, 3) > x1 {
				x1 = player.FaGet(fa, k, 3)
			}
			if player.FaGet(fa, k, 4) > y1 {
				y1 = player.FaGet(fa, k, 4)
			}
			w = player.FaGet(fa, k, 7)
			s = evidence.WdGet(wd, w, evidence.HdTstart())
			e = s + evidence.WdGet(wd, w, evidence.HdTlen())
			for s < e {
				port.CellsPush(tt, port.CellsAt(et, s))
				s += 1
			}
			k += 1
		}
		lr = model.LedgerAdd(ledger, player.FaGet(fa, i, 5), player.FaGet(fa, i, 0), x0, y0, x1, y1, 1000, model.SrText())
		t0 = port.CellsLen(text)
		normalize.NzNfc(tt, 0, port.CellsLen(tt), text, tmp, normalize.NzFlagLigatures()+normalize.NzFlagRadicals())
		model.LedgerSetText(ledger, lr, t0, port.CellsLen(text)-t0)
		rows += 1
		i = j
	}
	return rows
}
